static#shapeOf(text){
const parsed=parseClipboardText(text);
if(!parsed||!parsed.length)return null;
let cols=0;
for(const row of parsed)if(row.length>cols)cols=row.length;
return cols?{rows:parsed.length,cols}:null;
}
